package com.example.meetomxh.supabase;
import android.app.Activity;
import android.app.AlertDialog;
import android.widget.*;
import com.example.meetomxh.models.Chat;
import com.example.meetomxh.repositories.ChatRepository;
import org.json.*;
import java.util.*;
public final class ChatControls {
 private static void act(Activity a,String rpc,JSONObject input){ChatRepository.getInstance().action(rpc,input,new ChatRepository.OnMessageActionListener(){public void onSuccess(){Toast.makeText(a,"Đã cập nhật",Toast.LENGTH_SHORT).show();if(rpc.equals("leave_conversation"))a.finish();else if(a instanceof com.example.meetomxh.ChatActivity)((com.example.meetomxh.ChatActivity)a).refreshConversationState();}public void onError(String e){Toast.makeText(a,e,Toast.LENGTH_LONG).show();}});}
 public static void show(Activity a,Chat chat){Api.run(()->ChatRepository.getInstance().load(chat.getChatId()),new Api.Callback<Chat>(){public void success(Chat current){menu(a,current);}public void error(String e){Toast.makeText(a,e,Toast.LENGTH_LONG).show();}});}
 private static void menu(Activity a,Chat c){List<String> labels=new ArrayList<>(Arrays.asList("Thành viên","Rời nhóm"));if("admin".equals(c.role))labels.addAll(Arrays.asList("Thêm bạn vào nhóm","Đổi tên nhóm",c.state.equals("archived")?"Mở lại cuộc trò chuyện":"Lưu trữ cuộc trò chuyện"));new AlertDialog.Builder(a).setTitle(c.title).setItems(labels.toArray(new String[0]),(d,i)->{
  if(i==0)Api.run(()->(JSONArray)RpcClient.call("get_conversation_members",Api.obj("p_conversation_id",c.getChatId())),new Api.Callback<JSONArray>(){public void success(JSONArray rows){String[] names=new String[rows.length()];for(int j=0;j<rows.length();j++){JSONObject p=rows.optJSONObject(j);names[j]=(p.isNull("display_name")?"Thành viên":p.optString("display_name"))+" · "+p.optString("role");}new AlertDialog.Builder(a).setTitle("Thành viên").setItems(names,(dialog,index)->{JSONObject member=rows.optJSONObject(index);if(!"admin".equals(c.role)||SessionManager.getInstance().uid().equals(member.optString("user_id")))return;new AlertDialog.Builder(a).setItems(new String[]{"Loại thành viên","Đặt quản trị viên","Đặt thành viên"},(x,n)->act(a,"manage_conversation_member",Api.obj("p_conversation_id",c.getChatId(),"p_target",member.optString("user_id"),"p_action",new String[]{"remove","promote","demote"}[n]))).show();}).show();}public void error(String e){Toast.makeText(a,e,Toast.LENGTH_LONG).show();}});
  if(i==1)act(a,"leave_conversation",Api.obj("p_conversation_id",c.getChatId()));
  if(i==2)chooseFriend(a,(id)->act(a,"manage_conversation_member",Api.obj("p_conversation_id",c.getChatId(),"p_target",id,"p_action","add")));
  if(i==3){EditText name=new EditText(a);name.setText(c.title);new AlertDialog.Builder(a).setTitle("Đổi tên nhóm").setView(name).setPositiveButton("Lưu",(x,n)->act(a,"rename_conversation",Api.obj("p_conversation_id",c.getChatId(),"p_title",name.getText().toString(),"p_expected_version",c.version))).setNegativeButton("Hủy",null).show();}
  if(i==4)act(a,"set_conversation_state",Api.obj("p_conversation_id",c.getChatId(),"p_state",c.state.equals("archived")?"active":"archived","p_expected_version",c.version));
 }).show();}
 interface Pick {void selected(String id);}
 private static void chooseFriend(Activity a,Pick pick){Api.run(()->(JSONArray)RpcClient.call("get_friends",Api.obj("p_limit",50)),new Api.Callback<JSONArray>(){public void success(JSONArray rows){String[] names=new String[rows.length()];for(int i=0;i<rows.length();i++)names[i]=rows.optJSONObject(i).optString("display_name","Bạn bè");new AlertDialog.Builder(a).setTitle("Chọn bạn bè").setItems(names,(d,i)->pick.selected(rows.optJSONObject(i).optString("id"))).show();}public void error(String e){Toast.makeText(a,e,Toast.LENGTH_LONG).show();}});}
 public static void create(Activity a){chooseFriend(a,id->{EditText title=new EditText(a);title.setHint("Tên nhóm chat");new AlertDialog.Builder(a).setTitle("Tạo nhóm chat").setView(title).setPositiveButton("Tạo",(d,i)->{String fingerprint=title.getText().toString()+id;Api.run(()->{JSONObject r=RpcClient.object("create_group_conversation",Api.obj("p_title",title.getText().toString(),"p_members",Api.array(id),"p_client_request_id",RequestIds.get("chat_group",fingerprint)));RequestIds.complete("chat_group",fingerprint);return r.getString("id");},new Api.Callback<String>(){public void success(String cid){a.startActivity(new android.content.Intent(a,com.example.meetomxh.ChatActivity.class).putExtra("chat_id",cid));}public void error(String e){Toast.makeText(a,e,Toast.LENGTH_LONG).show();}});}).setNegativeButton("Hủy",null).show();});}
 public static void receipts(Activity a,String conversation,String message){Api.run(()->(JSONArray)RpcClient.call("get_read_receipts",Api.obj("p_conversation_id",conversation,"p_message_id",message)),new Api.Callback<JSONArray>(){public void success(JSONArray rows){StringBuilder text=new StringBuilder();for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);text.append(r.optString("user_id")).append(" · ").append(r.optBoolean("read")?"Đã đọc":r.optBoolean("delivered")?"Đã giao":"Đã gửi").append("\n");}new AlertDialog.Builder(a).setTitle("Xác nhận từ thiết bị thành viên").setMessage(rows.length()==0?"Chưa có người nhận hợp lệ":text.toString()).setPositiveButton("Đóng",null).show();}public void error(String e){Toast.makeText(a,e,Toast.LENGTH_LONG).show();}});}}
